-- Wald/logseries independent NumPy 2.3.5 differential oracle
local np=require("luaray_core")
assert(np._version=="0.104.0-dev")
local checks=0
local function eq(a,b) assert(a==b,("check %d: %s ~= %s"):format(checks,tostring(a),tostring(b))); checks=checks+1 end
local function eqnum(a,b) if b~=b then assert(a~=a,"expected NaN "..checks) else assert(a==b,("check %d: %.17g ~= %.17g"):format(checks,a,b)) end; checks=checks+1 end
do local r=np.random.default_rng(0); local v=r:wald(0x1.0000000000000p+0,0x1.0000000000000p+0,nil)
eqnum(v,0x1.c38bc15fafdeep-1)
eq(r:raw_hex(),"0a7d3da94ecde8b8") end
do local r=np.random.default_rng(0); local v=r:wald(0x1.0000000000000p+0,0x1.0000000000000p+0,{})
eq(v.dtype,"float64")
eq(#v.shape,0)
eqnum(v:get(),0x1.c38bc15fafdeep-1)
eq(r:raw_hex(),"0a7d3da94ecde8b8") end
